"},{"node":"getContainerDSN","qualified_name":"bench-repo.store.test.getContainerDSN","label":"Function","file":"store/test/containers.go","start_line":360,"end_line":382,"in_degree":1,"out_degree":0,"match_lines":[370,373,375],"source":"func getContainerDSN(driver, hostDSN string) (string, error) {
	switch driver {
	case "mysql":
		cfg, err := mysqldriver.ParseDSN(hostDSN)
		if err != nil {
			return "", errors.Wrap(err, "failed to parse mysql dsn")
		}
		cfg.Net = "tcp"
		cfg.Addr = net.JoinHostPort(mysqlNetworkAlias, "3306")
		return cfg.FormatDSN(), nil
	case "postgres":
		u, err := url.Parse(hostDSN)
		if err != nil {
			return "", errors.Wrap(err, "failed to parse postgres dsn")
		}
		u.Host = net.JoinHostPort(postgresNetworkAlias, "5432")
		return u.String(), nil
	case "sqlite":
		return hostDSN, nil
	default:
		return "", errors.Errorf("unsupported driver for container dsn: %s", driver)
	}
}
