"},{"node":"tableExists","qualified_name":"bench-repo.store.test.tableExists","label":"Function","file":"store/test/migrator_upgrade_test.go","start_line":251,"end_line":271,"in_degree":1,"out_degree":0,"match_lines":[264],"source":"func tableExists(ctx context.Context, db *sql.DB, driver, table string) (bool, error) {
	switch driver {
	case "sqlite":
		var name string
		err := db.QueryRowContext(ctx, "SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?", table).Scan(&name)
		if err == sql.ErrNoRows {
			return false, nil
		}
		return err == nil, err
	case "mysql":
		var count int
		err := db.QueryRowContext(ctx, "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = ?", table).Scan(&count)
		return count > 0, err
	case "postgres":
		var regclass sql.NullString
		err := db.QueryRowContext(ctx, "SELECT to_regclass($1)", "public."+table).Scan(&regclass)
		return regclass.Valid && strings.EqualFold(regclass.String, table), err
	default:
		return false, errors.Errorf("unsupported driver: %s", driver)
	}
}
"},{"node":"getTestingProfileForDriver","qualified_name":"bench-repo.store.test.getTestingProfileForDriver","label":"Function","file":"store/test/store.go","start_line":75,"end_line":103,"in_degree":1,"out_degree":4,"match_lines":[90],"source":"func getTestingProfileForDriver(t *testing.T, driver string) *profile.Profile {
	// Attempt to load .env file if present (optional, for local development)
	_ = godotenv.Load(".env")

	// Get a temporary directory for the test data.
	dir := t.TempDir()
	mode := "prod"
	port := getUnusedPort()

	var dsn string
	switch driver {
	case "sqlite":
		dsn = fmt.Sprintf("%s/memos_%s.db", dir, mode)
	case "mysql":
		dsn = GetMySQLDSN(t)
	case "postgres":
		dsn = GetPostgresDSN(t)
	default:
		t.Fatalf("unsupported driver: %s", driver)
	}

	return &profile.Profile{
		Port:    port,
		Data:    dir,
		DSN:     dsn,
		Driver:  driver,
		Version: version.GetCurrentVersion(),
	}
}
